double microprice(double bestBid, long long bidSz,
                  double bestAsk, long long askSz){
    long long tot = bidSz + askSz;
    if (tot == 0) return (bestBid + bestAsk) / 2.0;
    double I = (double)bidSz / tot;
    return bestAsk * I + bestBid * (1.0 - I);
}

def microprice(best_bid, bid_sz, best_ask, ask_sz):
    tot = bid_sz + ask_sz
    if tot == 0:
        return (best_bid + best_ask) / 2.0
    I = bid_sz / tot
    return best_ask * I + best_bid * (1.0 - I)
